package edu.eci.cvds.ECIReserves.service;import edu.eci.cvds.ECIReserves.model.Laboratory;import edu.eci.cvds.ECIReserves.repository.LaboratoryRepository;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.stereotype.Service;import java.time.LocalDateTime;import java.util.*;@Servicepublic class LaboratoryService {    private final LaboratoryRepository laboratoryRepository;    private final List<Laboratory> laboratories = new ArrayList<>();    @Autowired    public LaboratoryService(LaboratoryRepository laboratoryRepository) {        this.laboratoryRepository = laboratoryRepository;    }    public ArrayList<Laboratory>  getAvailableLabs(){ return new ArrayList<>();    }    public Laboratory addLab(Laboratory lab) {        if (!isOkLab(lab)) {            return null;        }        laboratories.add(lab);       return laboratoryRepository.save(lab);    }    public Laboratory updateLab(String id, Laboratory updatedLab){ return null;}    public void deleteLab(String id){        laboratoryRepository.deleteById(id);        Laboratory lab = getLabByID(id);        laboratories.remove(lab);    }    public ArrayList<Laboratory> findAvailableLabsBetween(LocalDateTime start, LocalDateTime end){ return new ArrayList<>();}    public boolean isLabAvailable(String labId, LocalDateTime start, LocalDateTime end){return false;}    public ArrayList<Laboratory> searchLabs(String name, Integer minCapacity, Integer minComputers, Boolean available){ return new ArrayList<>();}    public List<Laboratory> getLabsByName(String name) {        return laboratoryRepository.findByName(name);    }    public List<Laboratory> getLabsByCapacity(int minCapacity) {        return laboratoryRepository.findByCapacityGreaterThanEqual(minCapacity);    }    public List<Laboratory> getLabsByComputers(int minComputers) {        return laboratoryRepository.findByComputersGreaterThanEqual(minComputers);    }    public List<Laboratory> getLabsByOpeningTime(LocalDateTime openingTime) {        return laboratoryRepository.findByOpeningTime(openingTime);    }    public List<Laboratory> getLabsByClosingTime(LocalDateTime closingTime) {        return laboratoryRepository.findByClosingTime(closingTime);    }    private boolean isOkLab(Laboratory lab){        if(lab.getCapacity() <= 0){return false;}        if(lab.getId() == null){return false;}        if(lab.getName() == null){return false;}        if(lab.getDescription() == null){return false;}        if(lab.getComputers() < 0 || lab.getComputers() == null){ return false;}        if(lab.getOpeningTime() == null){return false;}        if(lab.getClosingTime() == null){return false;}        return true;    }    public Laboratory getLabByID(String id) {        for (Laboratory lab : laboratories) {            if (lab.getId().equals(id)) {                 return lab;            }        }        return null;    }}